WITH cleaned AS (SELECT *, COALESCE(revenue, 0) AS revenue_filled FROM store_sales WHERE product_id IN (3, 7, 8)), latest AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY store_id ORDER BY revenue_filled) AS dedup_rank FROM cleaned) x WHERE dedup_rank = 1), enriched AS (SELECT src.*, b.city, b.opened_date, b.store_name FROM latest src LEFT JOIN stores b ON src.store_id = b.id), scored AS (SELECT id, product_id, revenue, city, opened_date, store_name, DENSE_RANK() OVER (PARTITION BY city ORDER BY revenue_filled DESC) AS revenue_filled_dense_rank, LAST_VALUE(city, TRUE) OVER (PARTITION BY product_id, store_id ORDER BY dedup_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_city, ROW_NUMBER() OVER (ORDER BY revenue DESC, id) AS row_seq, FIRST_VALUE(revenue_filled, TRUE) OVER (PARTITION BY product_id, city ORDER BY revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_revenue_filled FROM enriched), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY first_known_revenue_filled DESC, id) AS latest_rank FROM scored) x WHERE latest_rank = 1), ranked_store_sales AS (SELECT * FROM ranked QUALIFY ROW_NUMBER() OVER (PARTITION BY city, product_id ORDER BY opened_date DESC, id) = 1), metrics AS (SELECT id, product_id, revenue, city, opened_date, store_name, revenue_filled_dense_rank, latest_rank, AVG(first_known_revenue_filled) OVER (ORDER BY opened_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS first_known_revenue_filled_avg_6, COUNT(revenue_filled_dense_rank) OVER (PARTITION BY product_id) AS product_id_count_revenue_filled_dense_rank, SUM(first_known_revenue_filled) OVER (PARTITION BY product_id ORDER BY revenue_filled_dense_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_first_known_revenue_filled, NTILE(3) OVER w_ordered AS first_known_revenue_filled_bucket, ROW_NUMBER() OVER w_grp AS row_seq_2 FROM ranked_store_sales WINDOW w_ordered AS (PARTITION BY product_id ORDER BY first_known_revenue_filled, id), w_grp AS (PARTITION BY city, product_id ORDER BY latest_rank, id)) SELECT s.id, s.product_id, s.revenue, s.city, s.opened_date, s.store_name, s.revenue_filled_dense_rank, s.product_id_count_revenue_filled_dense_rank, s.cumulative_first_known_revenue_filled, (SELECT MIN(t2.units) FROM store_sales t2 WHERE t2.product_id = s.product_id) AS min_store_sale_units FROM metrics s ORDER BY cumulative_first_known_revenue_filled DESC, revenue_filled_dense_rank DESC
